import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Atlas region: 512 × 320 pixels → aspect ratio 1.6:1
  const aspectRatio = 512 / 320;

  // Create plane geometry with matching aspect ratio
  const planeGeometry = new THREE.PlaneGeometry(aspectRatio, 1);

  // Load texture
  const imageUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const textureMap = ctx.textureLoader.load(imageUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create TSL texture node
  const textureNode = texture(textureMap);

  // Create material with texture node
  const material = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
    side: THREE.DoubleSide
  });

  // Create and add mesh
  const mesh = new THREE.Mesh(planeGeometry, material);
  group.add(mesh);

  // Setup cleanup handler
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Setup empty handlers object
  group.userData.handlers = {};

  return group;
}
